class Money private constructor(val cents: Long, val currency: Currency) {
    companion object {
        fun of(currency: Currency, amount: BigDecimal): Money =
            Money(amount.movePointRight(2).longValueExact(), currency)
        fun zero(currency: Currency): Money = Money(0, currency)
    }
}
